let DB = {};
const storage = {
  get: (k, d) => Promise.resolve(DB[k] === undefined ? (d === undefined ? '' : d) : JSON.parse(JSON.stringify(DB[k]))),
  set: (k, v) => { DB[k] = v; return Promise.resolve(true); },
  getAll: () => Promise.resolve(JSON.parse(JSON.stringify(DB))),
  saveAll: (o) => { DB = JSON.parse(JSON.stringify(o)); return Promise.resolve(true); }
};
const brightness = { setKeepScreenOn: () => {} };
const app = { terminate: () => {} };
const router = { clear: () => {} };
const global = globalThis;

// 池鱼单词 · 熟练度算法（手环端）
// 每个词只存一个「综合熟练度 p(0-100)」和「下次该问的时间 t」。
// p 由三件事共同决定：看到单词的反应时间、看释义的停留时长、以及这次学习发生的时刻；
// 下次推送时间由 p 反推间隔，再对齐到白天。

const DAY = 86400000
const HOUR = 3600000

function clamp(v, a, b) { return v < a ? a : (v > b ? b : v) }

// 反应时间系数：越快点掉，说明越熟
function rtFactor(rt) {
	if (!rt || rt <= 0) return 1
	if (rt <= 1200) return 1.25
	if (rt <= 3000) return 1.0
	if (rt <= 6000) return 0.85
	return 0.7
}

// 释义停留系数：停得久说明在认真看
function dwellFactor(d) {
	if (!d || d <= 0) return 1
	if (d >= 4000) return 1.2
	if (d >= 1500) return 1.0
	return 0.8
}

// 一次回答对熟练度的增量
function delta(action, rt, dwell) {
	var base = action === 'know' ? 18 : (action === 'fuzzy' ? -3 : -12)
	return base * rtFactor(rt) * dwellFactor(dwell)
}

// 熟练度 → 下次间隔（天）：p=0 约半小时，p=50 约 1.6 天，p=80 约 29 天
function gapDays(p) {
	return clamp(0.02 * Math.pow(2.4, clamp(p, 0, 100) / 10), 0.02, 60)
}

// 对齐到白天，避免凌晨叫人背单词
function alignDaytime(ts) {
	var d = new Date(ts)
	var h = d.getHours()
	if (h < 7) return ts + (7 - h) * HOUR
	if (h >= 23) return ts + (24 - h + 7) * HOUR
	return ts
}

// 紧急度：熟练度越低、过期越久、错得越多，越该被问到
function urgency(e) {
	var p = (e && typeof e.p === 'number') ? e.p : 0
	var t = (e && typeof e.t === 'number') ? e.t : 0
	var over = t ? Math.max(0, (Date.now() - t) / DAY) : 0
	var wc = (e && e.wc) ? e.wc : 0
	return (100 - p) * 0.6 + Math.min(over, 30) * 8 + Math.min(wc, 5) * 2 + Math.random() * 8
}

// 回答一次 → 新的词条状态 {p, t, c, wc, last}
// 规则（按用户实际用法定）：
//   认识 → 熟练度涨，下次按遗忘曲线（几小时后 ~ 几十天后）
//   模糊 → 熟练度略降，2 小时后再问一次
//   不会 → 熟练度腰斩，10 分钟后再问一次（就是"多问几遍"）
function answer(entry, action, rt, dwell) {
	var e = entry || {}
	var p = (typeof e.p === 'number') ? e.p : 0
	var c = e.c || 0
	var wc = e.wc || 0
	var f = rtFactor(rt) * dwellFactor(dwell)
	var now = Date.now()
	var t
	if (action === 'know') {
		p = clamp(p + 18 * f, 0, 100)
		c++
		t = alignDaytime(now + gapDays(p) * DAY)
	} else if (action === 'fuzzy') {
		p = clamp(p * 0.9 - 2, 0, 100)
		t = now + 2 * HOUR
	} else {
		p = clamp(p * 0.5, 0, 100)
		wc++
		t = now + 10 * 60 * 1000
	}
	return { p: p, t: t, c: c, wc: wc, last: now, a: action }
}
const srs = {
	rtFactor: rtFactor,
	dwellFactor: dwellFactor,
	gapDays: gapDays,
	urgency: urgency,
	answer: answer
}










// ===== 词库：4678 词内置，但不拆成对象数组 =====
// 只记录每行起始偏移，用到哪个词才截哪一行，避免一次性建 4678 个对象把内存撑爆。
var _off = null

function offsets() {
	if (_off) return _off
	var a = [0], s = DICT, n = s.length
	for (var i = 0; i < n; i++) {
		if (s.charCodeAt(i) === 10) a.push(i + 1)
	}
	_off = a
	return a
}

function dictCount() { return offsets().length }

function dictWord(i) {
	var o = offsets()
	if (i < 0 || i >= o.length) return null
	var end = (i + 1 < o.length) ? o[i + 1] - 1 : DICT.length
	var line = DICT.substring(o[i], end)
	var t = line.indexOf('\t')
	if (t < 0) return { i: i, w: line, m: '', core: 0 }
	var w = line.substring(0, t)
	return { i: i, w: w, m: line.substring(t + 1), core: (CORE.charCodeAt(i) === 49 ? 1 : 0) }
}

function pad2(n) { return (n < 10 ? '0' : '') + n }

function todayStr() {
	var d = new Date()
	return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate())
}

function timeStr(ts) {
	var d = new Date(ts)
	return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate()) +
		' ' + pad2(d.getHours()) + ':' + pad2(d.getMinutes()) + ':' + pad2(d.getSeconds())
}

const DAILY_NEW = 100000  // 新词上限（改为不限；想恢复限制就改回 30）
const REC_KEEP = 800      // 本地最多保留多少条记录（供手机周同步）
const KNOWN_P = 40        // 熟练度 ≥ 40 也算「认识」（多次答对后即使最近点了模糊也保留）


// ===== 存储缓存：整个 db 只读入一次，答题时只改内存，攒几次再写盘 =====
var _db = null
var _pend = 0

function loadDb() {
	if (_db) return Promise.resolve(_db)
	return storage.getAll().then(function (d) {
		_db = d || {}
		return _db
	})
}

function persist(force) {
	if (!_db) return Promise.resolve()
	_pend++
	if (!force && _pend < 6) return Promise.resolve()
	_pend = 0
	try {
		return storage.saveAll(_db)
	} catch (e) {
		return Promise.resolve()
	}
}

const PAGE = {
	private: {
		mode: 'home',            // home | study | meaning | done
		curWord: { w: '', m: '', i: -1, ph: 0 },
		totalCount: 0,
		knownCount: 0,
		seenCount: 0,
		coreKnown: 0,
		extraKnown: 0,
		coreTotal: 0,
		extraTotal: 0,
		coreTag: '',
		scopeText: '只看核心词',
		pct: 0,
		sessionCount: 0,
		lastActText: '',
		animClass: 'animIn',
		debug: ''
	},

	touch: { sx: 0, sy: 0, active: false },
	_onlyCore: 1,
	_shownAt: 0,
	_meaningAt: 0,
	_act: '',
	_rt: 0,

	onShow() {
		var that = this
		this.totalCount = dictCount()
		var cn = 0
		for (var i = 0; i < CORE.length; i++) { if (CORE.charCodeAt(i) === 49) cn++ }
		this.coreTotal = cn
		this.extraTotal = this.totalCount - cn
		this.sessionCount = 0
		var that0 = this
		storage.get('only_core', 1).then(function (v) {
			that0._onlyCore = (v === 0 || v === false) ? 0 : 1
			that0.scopeText = that0._onlyCore ? '只看核心词' : '核心+扩展'
		})
		this.refreshStats()
		// 与手机握手
		try { globalThis.conn && globalThis.conn.send('__hs__', { count: 1 }) } catch (e) { }
	},

	// 统计：只遍历「学过的词」，不扫全库
	refreshStats() {
		var that = this
		loadDb().then(function (_d) {
			var map = (_d && _d.map) || {}
			var known = 0, ck = 0, ek = 0, seen = 0
			for (var k in map) {
				var e = map[k]
				if (!e || typeof e.p !== 'number') continue
				seen++
				// 认不认识，看两件事：最近一次点的是"认识"，或熟练度已经足够高
				// 只要最近一次点的是「认识」就算掌握（读得慢的人熟练度涨得少，不能因此判成没背会）
				var ok = (e.a === 'know') || e.p >= KNOWN_P
				if (!ok) continue
				known++
				if (CORE.charCodeAt(parseInt(k, 10)) === 49) ck++
				else ek++
			}
			that.knownCount = known
			that.seenCount = seen
			that.coreKnown = ck
			that.extraKnown = ek
			that.pct = Math.round(known / that.totalCount * 1000) / 10
		})
	},

	// 切换背诵范围：只背核心 / 核心+扩展
	toggleScope() {
		this._onlyCore = this._onlyCore ? 0 : 1
		this.scopeText = this._onlyCore ? '只看核心词' : '核心+扩展'
		storage.set('only_core', this._onlyCore)
	},

	startRound() {
		this.sessionCount = 0
		this.debug = ''
		this.pickNext()
	},

	// 取下一个该背的词：先到期复习词，再新词，都没有就收工
	pickNext() {
		var that = this
		this.debug = ''
		loadDb().then(function (db) {
			db = db || {}
			var map = db.map || {}
			var now = Date.now()

			// 1) 到期词里挑最急的一个（只遍历学过的词）
			var onlyCore = that._onlyCore ? 1 : 0
			var best = -1, bestU = -1
			for (var k in map) {
				var e = map[k]
				if (!e) continue
				if (e.t && e.t > now) continue
				if (onlyCore && CORE.charCodeAt(parseInt(k, 10)) !== 49) continue
				var u = srs.urgency(e)
				if (u > bestU) { bestU = u; best = parseInt(k, 10) }
			}
			if (best >= 0) {
				that.showWord(best)
				return
			}

			// 2) 新词：随机抽一个没学过的，受每日配额限制
			var day = todayStr()
			var newCnt = (db.lastNewDay === day) ? (db.newLearned || 0) : 0
			if (newCnt >= DAILY_NEW) {
				that.mode = 'done'
				try { brightness.setKeepScreenOn({ keepScreenOn: false }) } catch (e) { }
				return
			}
			var total = dictCount()
			var idx = -1
			for (var g = 0; g < 200; g++) {
				var r = Math.floor(Math.random() * total)
				if (map[r]) continue
				if (onlyCore && CORE.charCodeAt(r) !== 49) continue
				idx = r
				break
			}
			if (idx < 0) {
				that.mode = 'done'
				try { brightness.setKeepScreenOn({ keepScreenOn: false }) } catch (e) { }
				return
			}
			db.lastNewDay = day
			db.newLearned = newCnt + 1
			persist()
			that.showWord(idx)
		})
	},

	showWord(i) {
		var wd = dictWord(i)
		if (!wd) { this.mode = 'done'; return }
		this.curWord = wd
		this._shownAt = Date.now()
		this._act = ''
		this._rt = 0
		this.mode = 'study'
		this.animClass = 'animIn'
		this.coreTag = wd.core ? '高考核心' : '扩展词'
		this.sessionCount++
		try { brightness.setKeepScreenOn({ keepScreenOn: true }) } catch (e) { }
	},

	chooseBtn(action) {
		this.choose(action, Date.now() - this._shownAt)
	},

	choose(action, rt) {
		this._act = action
		this._rt = rt
		this.lastActText = action === 'know' ? '认识 ✓' : (action === 'fuzzy' ? '模糊 ~' : '不会 ✗')
		this.mode = 'meaning'
		this._meaningAt = Date.now()
	},

	nextWord() {
		var that = this
		var cw = this.curWord
		var dwell = Date.now() - this._meaningAt
		var act = this._act || 'fuzzy'
		var rt = this._rt

		// 只改内存缓存，不等写盘；每 6 题或退出时统一落盘
		loadDb().then(function (db) {
			db = db || {}
			var map = db.map || {}
			var ne = srs.answer(map[cw.i] || {}, act, rt, dwell)
			map[cw.i] = ne
			db.map = map
			var recs = db.records || []
			recs.push({
				word: cw.w,
				action: act,
				t: timeStr(Date.now()),
				rt: rt,
				d: dwell,
				p: ne.p
			})
			if (recs.length > REC_KEEP) recs = recs.slice(recs.length - REC_KEEP)
			db.records = recs
			persist()
			return null
		}).then(function () {
			that.refreshStats()
			that.pickNext()
		})
	},

	onTouchStart(e) {
		var t = e.touches[0]
		this.touch.sx = t.clientX
		this.touch.sy = t.clientY
		this.touch.active = true
	},

	onTouchMove() { },

	onTouchEnd(e) {
		if (!this.touch.active) return
		this.touch.active = false
		var t = (e && e.changedTouches && e.changedTouches[0]) ? e.changedTouches[0]
			: ((e && e.touches && e.touches[0]) || null)
		if (!t || typeof t.clientX !== 'number') return
		var dx = t.clientX - this.touch.sx
		var dy = t.clientY - this.touch.sy
		var ax = Math.abs(dx), ay = Math.abs(dy)
		var isTap = ax < 20 && ay < 20
		if (ax >= ay && dx > 0) { this.exitApp(); return }
		if (this.mode === 'meaning' && isTap) { this.nextWord(); return }
		if (isTap) return
		if (this.mode !== 'study') return
		var action = null
		if (ay > ax && dy < 0) action = 'fuzzy'
		else if (ay > ax && dy > 0) action = 'forget'
		else if (ax >= ay && dx < 0) action = 'know'
		if (action) this.choose(action, Date.now() - this._shownAt)
	},

	onHide() {
		persist(true)
	},

	exitApp() {
		persist(true)
		try { brightness.setKeepScreenOn({ keepScreenOn: false }) } catch (e) { }
		try { app.terminate() } catch (e) { }
		setTimeout(function () {
			try { router.clear() } catch (e) { }
		}, 300)
	},

	onBackPress() {
		if (this.mode === 'study' || this.mode === 'meaning') {
			this.mode = 'home'
			this.refreshStats()
			try { brightness.setKeepScreenOn({ keepScreenOn: false }) } catch (e) { }
		} else {
			this.exitApp()
		}
		return true
	}
}


Object.assign(PAGE, PAGE.private || {});   // 模拟框架把 private 映射到实例
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
let fails = 0;
const check = (n, ok, ex) => {
  console.log((ok ? 'PASS  ' : 'FAIL  ') + n + (ex !== undefined ? '  [' + ex + ']' : ''));
  if (!ok) fails++;
};

// ---- 首页统计 ----
PAGE.onShow();
await sleep(40);
check('词库总数 4678', PAGE.totalCount === 4678, PAGE.totalCount);
check('初始已认识 0', PAGE.knownCount === 0, PAGE.knownCount);
check('初始百分比 0', PAGE.pct === 0, PAGE.pct);
check('核心词 3573 / 扩展 1105', PAGE.coreTotal === 3573 && PAGE.extraTotal === 1105,
  PAGE.coreTotal + '/' + PAGE.extraTotal);

// ---- 开始背 ----
PAGE.startRound();
await sleep(40);
check('进入背词模式', PAGE.mode === 'study', PAGE.mode);
check('拿到词且有释义', !!PAGE.curWord.w && !!PAGE.curWord.m, PAGE.curWord.w);
check('curWord 带索引', typeof PAGE.curWord.i === 'number', PAGE.curWord.i);

const firstWord = PAGE.curWord.w;
const firstIdx = PAGE.curWord.i;

// ---- 背 5 个后「退出」 ----
for (let n = 0; n < 5; n++) {
  PAGE.chooseBtn('know');
  check('答题后进释义 #' + n, PAGE.mode === 'meaning', PAGE.mode);
  PAGE.nextWord();
  await sleep(20);
}
check('本次已显示第 6 个词', PAGE.sessionCount === 6, PAGE.sessionCount);
PAGE.onHide();          // 触发落盘（现在攒批写盘）
await sleep(30);
const mapAfter5 = Object.keys(DB.map || {}).length;
check('5 个词已入库', mapAfter5 === 5, mapAfter5);

// ---- 模拟退出重进：重新 onShow ----
PAGE.mode = 'home';
PAGE.onShow();
await sleep(40);
check('重进后本次计数归零', PAGE.sessionCount === 0, PAGE.sessionCount);
check('重进后进度保留 5 个', PAGE.knownCount === 5, PAGE.knownCount);
check('百分比 > 0', PAGE.pct > 0 && PAGE.pct < 1, PAGE.pct);

// ---- 再开始：不应该把刚背过的 5 个重新给一遍 ----
PAGE.startRound();
await sleep(40);
check('新一轮仍在背词模式', PAGE.mode === 'study', PAGE.mode);
check('不会立刻重复上一个词', PAGE.curWord.w !== firstWord || PAGE.curWord.i !== firstIdx,
  PAGE.curWord.w);
