check('已学数 > 0', PAGE.seenCount >= 1, PAGE.seenCount);

// ---- 算法单调性 ----
const e1 = srs.answer({}, 'know', 800, 4000);
const e2 = srs.answer(e1, 'know', 800, 4000);
