check('越熟问得越晚', (e2.t - Date.now()) > (e1.t - Date.now()),
  Math.round((e1.t - Date.now()) / 3600000) + 'h -> ' + Math.round((e2.t - Date.now()) / 3600000) + 'h');
check('不会→熟练度腰斩', e3.p < e2.p / 2 + 10, e2.p + ' -> ' + e3.p);
